# Essential imports (guaranteed to be available)
import os
import torch
import torch.nn as nn
import torch.nn.functional as F
import torch.optim as optim
from dataset import get_dataloader
import json
from tqdm import tqdm
import numpy as np
from sklearn.metrics import roc_auc_score


# Define hyperparameters based on iteration number (Iteration 6)
iteration = 6
batch_size = [8, 16, 32][iteration % 3]
lr = [0.001, 0.0001, 0.00001][iteration % 3]
num_convs = [2, 3, 4][iteration % 3]
dropout_rate = 0.5
l2_reg = 0.0001

NUM_SPECIES = 206

# Data ingestion
DATA_DIR = "/mnt/disks/data/birdclef"
METADATA_FILE = os.path.join(DATA_DIR, "train.csv")
train_loader = get_dataloader(DATA_DIR, METADATA_FILE, batch_size=batch_size)

# Limit training dataset to 15000 samples
subset = torch.utils.data.Subset(train_loader.dataset, range(min(15000, len(train_loader.dataset))))
train_loader = torch.utils.data.DataLoader(subset, batch_size=batch_size, shuffle=True)

# Define the model architecture
class BirdClassifier(nn.Module):
    def __init__(self, num_convs, dropout_rate, l2_reg):
        super(BirdClassifier, self).__init__()
        channels = [32, 64, 128, 256][:num_convs]
        
        conv_layers = []
        for i in range(num_convs):
            if i == 0:
                in_channels = 1
            else:
                in_channels = channels[i-1]
            out_channels = channels[i]
            conv_layers.extend([
                nn.Conv2d(in_channels, out_channels, kernel_size=3, padding=1),
                nn.BatchNorm2d(out_channels),
                nn.ReLU(),
            ])
        
        self.conv_layers = nn.Sequential(*conv_layers)
        self.pool = nn.AdaptiveAvgPool2d((1, 1))
        self.classifier = nn.Sequential(
            nn.Dropout(dropout_rate),
            nn.Linear(channels[-1], 128),
            nn.ReLU(),
            nn.Linear(128, NUM_SPECIES),
        )
    
    def forward(self, x):
        x = self.conv_layers(x)
        x = self.pool(x).view(x.size(0), -1)
        return torch.sigmoid(self.classifier(x))

# Initialize model, loss function, and optimizer
model = BirdClassifier(num_convs=num_convs, dropout_rate=dropout_rate, l2_reg=l2_reg)
criterion = nn.BCELoss()
optimizer = optim.Adam(model.parameters(), lr=lr, weight_decay=l2_reg)

# Move model to GPU if available
device = torch.device("cuda" if torch.cuda.is_available() else "cpu")
model.to(device)

# Training loop
epochs = 6
for epoch in range(epochs):
    model.train()
    total_loss = 0.0
    for batch_idx, (inputs, labels) in enumerate(train_loader):
        inputs, labels = inputs.to(device), labels.to(device)
        
        optimizer.zero_grad()
        outputs = model(inputs)
        loss = criterion(outputs, labels.float())
        loss.backward()
        optimizer.step()
        
        total_loss += loss.item()
        torch.cuda.empty_cache()  # Prevent GPU fragmentation
    
    avg_train_loss = total_loss / len(train_loader)
    print(f"Epoch {epoch+1}/{epochs}, Train Loss: {avg_train_loss:.4f}")

# Evaluation loop
model.eval()
all_preds = []
all_labels = []

with torch.no_grad():
    for inputs, labels in train_loader:
        inputs, labels = inputs.to(device), labels.to(device)
        outputs = model(inputs)
        all_preds.append(outputs.cpu().numpy())
        all_labels.append(labels.cpu().numpy())

# Flatten predictions and labels
all_preds = np.concatenate(all_preds, axis=0)
all_labels = np.concatenate(all_labels, axis=0)


final_auc = roc_auc_score(all_labels, all_preds, average='weighted')
print(f"Final AUC: {final_auc:.4f}")

# Save metrics to JSON
metrics = {
    "final_train_loss": avg_train_loss,
    "final_auc": final_auc,
    "num_params": sum(p.numel() for p in model.parameters()),
    "epochs_trained": epochs,
    "batch_size": batch_size,
    "training_samples": 15000,
    "eval_samples": len(train_loader.dataset)
}

with open('metrics.json', 'w') as f:
    json.dump(metrics, f)

print("METRICS: " + json.dumps(metrics))

# Save model checkpoint
torch.save(model.state_dict(), 'model.pt')